<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { api } from '../platform';
import DateTimeField from './DateTimeField.vue';
import { type Row, eventCategories, statusNames, placementNames, adState, pollState, formatTime, localDateInput, fromLocalInput } from '../../../shared/domain';
import { useRequestScope } from '../../../shared/useRequestScope';
const props = defineProps<{ mode: 'activities' | 'ads' | 'polls'; user: Row | null }>();
const emit = defineEmits<{ (event: 'join'): void; (event: 'updated'): void }>();
const rows = ref<Row[]>([]), mine = ref<Row[]>([]), tab = ref(props.mode === 'activities' ? 'mine' : 'public'), screen = ref(''), selected = ref<Row>({}), form = ref<Row>({}), choices = ref<string[]>([]), error = ref(''), busy = ref(false);
const visible = computed(() => tab.value === 'mine' ? mine.value : rows.value);
const loading = ref(false);
let generation = 0, detailGeneration = 0;
const scope = useRequestScope();
onUnmounted(() => { ++generation; });
async function load() { const version = ++generation;loading.value = true;error.value = '';try { if (props.mode !== 'activities') { const data = await api(props.mode === 'ads' ? '/ads' : '/polls');if (version !== generation) return;rows.value = data; }if (props.user && props.mode !== 'polls') { const data = await api(props.mode === 'ads' ? '/my/ads' : '/my/event-proposals');if (version !== generation) return;mine.value = data; } }catch(e) { if (version === generation) error.value = (e as Error).message; } finally { if (version === generation) loading.value = false; } }
function member() { if (!props.user || props.user.status !== 'approved') { emit('join');return false; }return true; }
function create() { if (!member()) return;error.value = '';screen.value = 'create';const dates = { startsAt: localDateInput(new Date(Date.now() + 86400000)), endsAt: localDateInput(new Date(Date.now() + 2 * 86400000)) };form.value = props.mode === 'ads' ? { title: '', sponsor: '', content: '', placement: 'home', url: '', contact: '', consent: false, ...dates } : { title: '', description: '', category: eventCategories[0], location: '', capacity: 20, ...dates }; }
async function act(action: () => Promise<any>, text: string, keep = false) {
  if (busy.value) return;const current = scope.capture(), id = selected.value.id;busy.value = true;error.value = '';
  try { await action();if (!current()) return;if (!keep) screen.value = '';uni.showToast({ title: text, icon: 'none' });await load();if (current()) emit('updated'); }
  catch(e) { if (current()) error.value = (e as Error).message; }finally { if (current()) busy.value = false; }
}
function save() { act(() => api(props.mode === 'ads' ? '/ads' : '/event-proposals', 'POST', { ...form.value, startsAt: fromLocalInput(form.value.startsAt), endsAt: fromLocalInput(form.value.endsAt), capacity: Number(form.value.capacity) }), '申请已提交审核'); }
function choose(event: any) { if (props.mode === 'ads') form.value.placement = ['home', 'events'][Number(event.detail.value)];else form.value.category = eventCategories[Number(event.detail.value)]; }
function copy(value: string) { uni.setClipboardData({ data: value }); }
function consent(event: any) { form.value.consent = Boolean(event.detail.value); }
function select(event: any) { choices.value = event.detail.value; }
function detail(row: Row) { selected.value = row;choices.value = [...(row.myChoices || [])];screen.value = 'detail';error.value = ''; }
function withdraw(row: Row) { const current = scope.capture();uni.showModal({ title: '撤下广告', content: '确认撤下后将立即停止展示。', success: result => { if (result.confirm && current()) act(() => api('/ads/' + row.id + '/withdraw', 'POST'), '已撤下'); } }); }
watch([() => props.mode, () => props.user?.id, () => props.user?.status, () => props.user?.role], () => { scope.invalidate();++detailGeneration;busy.value = false;selected.value = {};form.value = {};error.value = '';screen.value = '';choices.value = [];++generation;rows.value = [];mine.value = [];screen.value = '';tab.value = props.mode === 'activities' ? 'mine' : 'public';load(); }, { flush: 'sync' });
onMounted(load);
</script>
<template><view class="engagement-mobile"><view v-if="error" class="error">{{ error }}<button v-if="!screen" class="text-button" :disabled="loading" @click="load">重新加载</button></view><view v-if="loading && !screen" class="loading">正在加载…</view><template v-if="!screen"><view v-if="mode !== 'activities'" class="title">{{ mode === 'ads' ? '合作展示，连接更多老乡' : '一起商量，一起决定' }}</view><view class="intro">{{ mode === 'polls' ? '每场仅提交一次，不公开个人选择；投票后或结束后可看汇总。' : mode === 'ads' ? '人工审核、按期展示，广告明确标识，暂不接在线支付。' : '有个好点子？发起一场老乡活动，审核后开放报名。' }}</view><button v-if="mode !== 'polls'" class="primary" @click="create">{{ mode === 'ads' ? '＋ 申请广告展示' : '＋ 发起活动' }}</button><view class="divider"/><view class="pill-row"><text v-if="mode !== 'activities'" :class="['pill', { active: tab === 'public' }]" @click="tab = 'public'">{{ mode === 'polls' ? '会员投票' : '当前展示' }}</text><text v-if="user && mode !== 'polls'" :class="['pill', { active: tab === 'mine' }]" @click="tab = 'mine'">{{ mode === 'ads' ? '我的投放申请' : '我的活动发起' }}</text></view><view v-if="!loading && !error && !visible.length && (mode !== 'activities' || user)" class="empty">{{ mode === 'polls' ? '暂时没有投票，欢迎常来看看。' : mode === 'ads' ? '暂时没有展示记录。' : '还没有发起活动。' }}</view><view v-for="row in visible" :key="row.id" class="panel"><view class="row"><text class="tag">{{ mode === 'polls' ? pollState(row) : mode === 'ads' ? tab === 'public' ? '广告 · 展示中' : adState(row) : statusNames[row.status] }}</text><text class="muted">{{ mode === 'ads' ? placementNames[row.placement] : row.category }}</text></view><text class="card-title" @click="detail(row)">{{ row.title }}</text><view class="post-excerpt">{{ row.content || row.description }}</view><view class="meta">{{ formatTime(row.startsAt) }} — {{ formatTime(row.endsAt) }}</view><view v-if="row.reviewNote" class="safe-note">{{ row.reviewNote }}</view><view class="card-actions"><text class="muted">{{ mode === 'polls' ? row.hasVoted ? '已投票' : row.maxChoices === 1 ? '单选' : '最多选' + row.maxChoices + '项' : mode === 'ads' ? row.sponsor : row.eventId ? '已转为正式活动' : '审核后公开报名' }}</text><button class="text-button" @click="detail(row)">{{ mode === 'polls' ? '查看投票' : '查看详情' }}</button></view><button v-if="mode === 'ads' && tab === 'mine' && ['pending', 'approved'].includes(row.status)" class="text-button" @click="withdraw(row)">撤下广告</button></view></template>
    <template v-else><button class="detail-back" :disabled="busy" @click="screen = ''; error = ''">← 返回</button><view class="form-page"><template v-if="screen === 'create'"><view class="form-title">{{ mode === 'ads' ? '申请广告展示' : '发起活动申请' }}</view><view class="field"><text class="field-label">标题</text><input v-model="form.title" :maxlength="mode === 'ads' ? 60 : 80"/></view><template v-if="mode === 'ads'"><view class="field"><text class="field-label">广告主 / 合作方名称</text><input v-model="form.sponsor" maxlength="60"/></view><view class="field"><text class="field-label">广告内容（10–800字）</text><textarea v-model="form.content" maxlength="800"/></view><view class="field"><text class="field-label">展示位置</text><picker :range="['首页推荐位', '活动页面']" @change="choose"><view class="outline small">{{ placementNames[form.placement] }} ▾</view></picker></view><view class="field"><text class="field-label">详情链接（HTTPS，可不填）</text><input v-model="form.url" maxlength="500" placeholder="https://"/></view><view class="field"><text class="field-label">公开联系方式（选填）</text><input v-model="form.contact" maxlength="80"/></view></template><template v-else><view class="field"><text class="field-label">活动类型</text><picker :range="eventCategories" @change="choose"><view class="outline small">{{ form.category }} ▾</view></picker></view><view class="field"><text class="field-label">活动地点</text><input v-model="form.location" maxlength="150"/></view><view class="field"><text class="field-label">人数上限</text><input v-model="form.capacity" type="number" maxlength="5"/></view><view class="field"><text class="field-label">活动详情（10–5000字）</text><textarea v-model="form.description" maxlength="5000" placeholder="说明安排、集合地点、参与须知"/></view></template><DateTimeField v-model="form.startsAt" label="开始时间"/><DateTimeField v-model="form.endsAt" label="结束时间"/><view v-if="mode === 'ads'" class="checkbox-row"><text class="switch-label">我确认内容真实，并同意公开展示合作方和所填联系信息。</text><switch :checked="form.consent" color="#174d6b" @change="consent"/></view><button class="primary" :disabled="busy" @click="save">提交审核</button></template>
    <template v-else><text class="card-title">{{ selected.title }}</text><view class="prose content-text">{{ selected.description || selected.content }}</view><view class="meta">{{ formatTime(selected.startsAt) }} — {{ formatTime(selected.endsAt) }}（北京时间）</view><template v-if="mode === 'polls'"><text class="tag">{{ pollState(selected) }} · 最多选{{ selected.maxChoices }}项</text><checkbox-group @change="select"><label v-for="option in selected.options" :key="option.id" class="poll-option"><checkbox :value="option.id" :checked="choices.includes(option.id)" :disabled="selected.hasVoted || pollState(selected) !== '投票中'" color="#174d6b"/><text class="option-text">{{ option.text }}</text><text v-if="selected.resultsVisible" class="muted">{{ selected.counts[option.id] || 0 }}票</text></label></checkbox-group><view v-if="selected.resultsVisible" class="notice-line">共{{ selected.totalVotes }}位会员投票，个人选择不公开。{{ selected.maxChoices > 1 ? '多选合计票数可大于人数。' : '' }}</view><button v-if="!selected.hasVoted && !selected.ended" class="primary" :disabled="busy || !choices.length || choices.length > selected.maxChoices || pollState(selected) !== '投票中'" @click="member() && act(() => api('/polls/' + selected.id + '/vote', 'POST', { choices }), '投票已提交')">确认投票（提交后不可更改）</button></template><template v-else-if="mode === 'ads'"><view class="notice-line">广告主：{{ selected.sponsor }}<br/>公开联系：{{ selected.contact || '未填写' }}</view><button v-if="selected.url" class="text-button" @click="copy(selected.url)">复制广告详情链接</button></template><template v-else><view class="notice-line">{{ selected.location }} · {{ selected.capacity }}人<br/>审核状态：{{ statusNames[selected.status] }}<br/>{{ selected.reviewNote }}</view></template></template></view></template>
  </view></template>
<style scoped>.engagement-mobile{margin:35rpx 0}.poll-option{display:flex;align-items:center;gap:15rpx;border:1px solid #dce8e4;border-radius:10rpx;padding:25rpx 15rpx;margin:20rpx 0}.option-text{flex:1;font-size:27rpx;word-break:break-all}</style>
